// Hardcoded black is replaced with currentColor so text-* classes apply.

function make(inner: string, view_box: string) {
  return function Illo({ width = 240, height, className }: IlloProps) {
    return (
      <svg
        width={width}
        height={height ?? (width * 151) / 240}
        viewBox={view_box}
        fill="none"
        stroke="currentColor"
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        className={className}
        dangerouslySetInnerHTML={{ __html: inner }}
      />
    );
  };
}

